              "signatureExchanges": {
                "signature1": {
                  "attack": "Deafen",
                  "lines": [
                    {
                      "id": "galactic.b.saturn.battle.signature1",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "No more outside assistance. You will answer Team Galactic directly.",
                      "delivery": "React to the confirmed battle event; do not interrupt play.",
                      "voiceId": "galactic.b.saturn.battle.signature1"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature1.1",
                      "speaker": "Celebi",
                      "speakerId": "celebi",
                      "text": "You call it assistance as though having someone beside us is cheating.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature1.1"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature1.2",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "An uncontrolled connection is a weakness. Team Galactic removes weaknesses.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature1.2"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature1.3",
                      "speaker": "Mira",
                      "speakerId": "mira",
                      "text": "You followed Celebi because your instruments could not do this alone. Remember that.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature1.3"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature1.4",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "We intend to control the connection, not depend on its goodwill.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature1.4"
                    }
                  ]
                },
                "signature2": {
                  "attack": "Remove Lost",
                  "lines": [
                    {
                      "id": "galactic.b.saturn.battle.signature2",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "We can remove more than your route from the record. Watch carefully.",
                      "delivery": "React to the confirmed battle event; do not interrupt play.",
                      "voiceId": "galactic.b.saturn.battle.signature2"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature2.1",
                      "speaker": "Celebi",
                      "speakerId": "celebi",
                      "text": "If you remove the record, does that make it easier to ignore who was there?",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature2.1"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature2.2",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "Records exist to preserve what matters. The rest is interference.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature2.2"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature2.3",
                      "speaker": "Mira",
                      "speakerId": "mira",
                      "text": "That is an instruction about what to forget, not an explanation.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature2.3"
                    },
                    {
                      "id": "galactic.b.saturn.exchange.signature2.4",
                      "speaker": "Commander Saturn",
                      "speakerId": "saturn",
                      "text": "You may keep your objections. You will not keep this route.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "galactic.b.saturn.exchange.signature2.4"
                    }
                  ]
                }
              }
