                {
                  "id": "mind-games.b.slowking.after.depth3.4",
                  "speaker": "Tess",
                  "speakerId": "tess",
                  "text": "Ask someone a question whose answer I do not know.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "mind-games.a.slowking.after.depth3.4"
                },
                {
                  "id": "mind-games.b.slowking.after.depth3.5",
                  "speaker": "Celebi",
                  "speakerId": "celebi",
                  "text": "Would you like us to stay for a little while?",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "mind-games.a.slowking.after.depth3.5"
                },
                {
                  "id": "mind-games.b.slowking.after.depth3.6",
                  "speaker": "Tess",
                  "speakerId": "tess",
                  "text": "Yes. That is a good question.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "mind-games.a.slowking.after.depth3.6"
                }
