              "signatureExchanges": {
                "signature1": {
                  "attack": "Quaking Punch",
                  "lines": [
                    {
                      "id": "recovery.b.lysandre.battle.signature1",
                      "speaker": "Lysandre",
                      "speakerId": "lysandre",
                      "text": "Every tool you cannot reach becomes another reason to accept my terms.",
                      "delivery": "React to the confirmed battle event; do not interrupt play.",
                      "voiceId": "recovery.b.lysandre.battle.signature1"
                    },
                    {
                      "id": "recovery.b.lysandre.exchange.signature1.1",
                      "speaker": "Celebi",
                      "speakerId": "celebi",
                      "text": "You shut the tools away and then blame us for needing help.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "recovery.b.lysandre.exchange.signature1.1"
                    },
                    {
                      "id": "recovery.b.lysandre.exchange.signature1.2",
                      "speaker": "Lysandre",
                      "speakerId": "lysandre",
                      "text": "I offer an orderly solution. Your pride is what makes it painful.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "recovery.b.lysandre.exchange.signature1.2"
                    },
                    {
                      "id": "recovery.b.lysandre.exchange.signature1.3",
                      "speaker": "Ada",
                      "speakerId": "ada",
                      "text": "Your solution starts with surrendering every choice. We have read the terms.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "recovery.b.lysandre.exchange.signature1.3"
                    },
                    {
                      "id": "recovery.b.lysandre.exchange.signature1.4",
                      "speaker": "Lysandre",
                      "speakerId": "lysandre",
                      "text": "Then you understand what refusing them will cost.",
                      "delivery": "A direct reply to the previous speaker; leave the player room to read.",
                      "voiceId": "recovery.b.lysandre.exchange.signature1.4"
                    }
                  ]
                }
              }
