              "before": [
                {
                  "speaker": "Vale",
                  "text": "Give me the tower and I can get people moving.",
                  "id": "darkest.a.eternatus.brief.original-001",
                  "speakerId": "vale",
                  "delivery": "Conversational; respond to the preceding line.",
                  "voiceId": "darkest.a.eternatus.brief.original-001"
                },
                {
                  "speaker": "Celebi",
                  "text": "We will clear the way.",
                  "id": "darkest.a.eternatus.brief.original-002",
                  "speakerId": "celebi",
                  "delivery": "Conversational; respond to the preceding line.",
                  "voiceId": "darkest.a.eternatus.brief.original-002"
                }
              ],
              "after": [
                {
                  "speaker": "Narrator",
                  "text": "Eternatus withdraws. Evacuation begins through a narrow opening. This victory stands, but the array still receives commands from its central connection.",
                  "id": "darkest.a.eternatus.after.original-001",
                  "speakerId": "narrator",
                  "delivery": "Narration; observe rather than explain the emotion.",
                  "voiceId": "darkest.a.eternatus.after.original-001"
                },
                {
                  "speaker": "Celebi",
                  "text": "Something on the other side is keeping it running.",
                  "id": "darkest.a.eternatus.after.original-002",
                  "speakerId": "celebi",
                  "delivery": "Conversational; respond to the preceding line.",
                  "voiceId": "darkest.a.eternatus.after.original-002"
                },
                {
                  "id": "darkest.after-dark-sky.a.01",
                  "speaker": "Narrator",
                  "text": "A narrow opening appears in the canopy. Someone in the shelter begins to count the stars and loses their place.",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "narrator",
                  "voiceId": "darkest.after-dark-sky.a.01"
                },
                {
                  "id": "darkest.after-dark-sky.a.02",
                  "speaker": "Vale",
                  "text": "Look at it for a moment. The tower can spare us that.",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "vale",
                  "voiceId": "darkest.after-dark-sky.a.02"
                },
                {
                  "id": "darkest.after-dark-sky.a.03",
                  "speaker": "Celebi",
                  "text": "I had forgotten how far away a sky could be.",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "celebi",
                  "voiceId": "darkest.after-dark-sky.a.03"
                },
                {
                  "id": "darkest.after-dark-sky.a.04",
                  "speaker": "You",
                  "text": "Did you get everyone through the opening?",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "player",
                  "voiceId": "darkest.after-dark-sky.a.04"
                },
                {
                  "id": "darkest.after-dark-sky.a.05",
                  "speaker": "Vale",
                  "text": "The first group. There are more. But the first group is through.",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "vale",
                  "voiceId": "darkest.after-dark-sky.a.05"
                },
                {
                  "id": "darkest.after-dark-sky.a.06",
                  "speaker": "Narrator",
                  "text": "She says it again, more quietly, where only the two of you can hear.",
                  "delivery": "brief relief; do not rush into another emergency",
                  "speakerId": "narrator",
                  "voiceId": "darkest.after-dark-sky.a.06"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.1",
                  "speaker": "Celebi",
                  "speakerId": "celebi",
                  "text": "I can see a little of the sky.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.1"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.2",
                  "speaker": "You",
                  "speakerId": "player",
                  "text": "We can stop and look at it.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.2"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.3",
                  "speaker": "Vale",
                  "speakerId": "vale",
                  "text": "I used to know the hour by that patch of roof.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.3"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.4",
                  "speaker": "Celebi",
                  "speakerId": "celebi",
                  "text": "Will you learn it again?",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.4"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.5",
                  "speaker": "Vale",
                  "speakerId": "vale",
                  "text": "I would like to be late for something ordinary.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.5"
                },
                {
                  "id": "darkest.a.eternatus.after.depth3.6",
                  "speaker": "You",
                  "speakerId": "player",
                  "text": "Let us give you the chance.",
                  "delivery": "Conversational; leave room for the answer.",
                  "voiceId": "darkest.a.eternatus.after.depth3.6"
                }
              ],
